--[[
    namdevHub 1.0.0 - single-file build
    Generated by tools/build.py. Do not edit; edit src/ and rebuild.
]]

local genv = (getgenv and getgenv()) or _G
if genv.__ScriptHub and genv.__ScriptHub.Unload then pcall(genv.__ScriptHub.Unload) end

local __sources = {}
__sources["src/core"] = [=[
--[[
    Script Hub - core framework
    ===========================
    Responsibilities:
      * work out which game the player is in,
      * pick the matching entry out of src/registry.lua,
      * build the Fluent window and the shared "Hub" tab,
      * hand each game module a context object and run it,
      * track everything the module creates so Unload really unloads.

    A game module never creates its own window. It gets ctx.Tab and uses
    ctx.Connect / ctx.Spawn / ctx.OnUnload so the hub can clean up after it.
]]

local Core = {}

local FLUENT_URL    = "https://github.com/dawid-scripts/Fluent/releases/latest/download/main.lua"
local SAVEMGR_URL   = "https://raw.githubusercontent.com/dawid-scripts/Fluent/master/Addons/SaveManager.lua"
local INTERFACE_URL = "https://raw.githubusercontent.com/dawid-scripts/Fluent/master/Addons/InterfaceManager.lua"

local Players           = game:GetService("Players")
local TeleportService   = game:GetService("TeleportService")
local MarketplaceService = game:GetService("MarketplaceService")
local HttpService       = game:GetService("HttpService")

local genv = (getgenv and getgenv()) or _G

--=========================================================================
-- Environment / game detection
--=========================================================================
local function getExecutorName()
    local ok, name = pcall(function()
        return identifyexecutor and identifyexecutor() or nil
    end)
    if ok and type(name) == "string" and name ~= "" then
        return name
    end
    return "Unknown"
end

local function getGameInfo()
    local info = {
        PlaceId = game.PlaceId,
        GameId  = game.GameId,
        JobId   = game.JobId,
        Name    = "Unknown game",
    }

    local ok, product = pcall(function()
        return MarketplaceService:GetProductInfo(game.PlaceId)
    end)
    if ok and type(product) == "table" and product.Name then
        info.Name = product.Name
    end

    return info
end

--=========================================================================
-- Registry matching
--
-- Priority: PlaceIds (exact) -> GameIds (universe) -> NameMatch (substring
-- of the marketplace name, lowercased). NameMatch means a new game works
-- before you have had a chance to write the id down.
--=========================================================================
local function matchesEntry(entry, info)
    if entry.Universal then return false end

    if entry.PlaceIds then
        for _, id in ipairs(entry.PlaceIds) do
            if tonumber(id) == info.PlaceId then return true, "PlaceId" end
        end
    end

    if entry.GameIds then
        for _, id in ipairs(entry.GameIds) do
            if tonumber(id) == info.GameId then return true, "GameId" end
        end
    end

    if entry.NameMatch and info.Name then
        local needle = tostring(entry.NameMatch):lower()
        if needle ~= "" and string.find(info.Name:lower(), needle, 1, true) then
            return true, "Name"
        end
    end

    return false
end

local function resolve(registry, info)
    local matched, universal = {}, {}
    for _, entry in ipairs(registry) do
        if entry.Universal then
            universal[#universal + 1] = entry
        else
            local hit, how = matchesEntry(entry, info)
            if hit then
                entry._matchedBy = how
                matched[#matched + 1] = entry
            end
        end
    end
    return matched, universal
end

--=========================================================================
-- Start
--=========================================================================
function Core.Start(config)
    local hub = {
        Config    = config,
        GameInfo  = getGameInfo(),
        Executor  = getExecutorName(),
        Unloaded  = false,
        _cleanup  = {},
        _threads  = {},
        _conns    = {},
        _loaded   = {},
    }

    ----------------------------------------------------------------- cleanup
    function hub.OnUnload(fn)
        hub._cleanup[#hub._cleanup + 1] = fn
    end

    function hub.Connect(signal, fn)
        local conn = signal:Connect(fn)
        hub._conns[#hub._conns + 1] = conn
        return conn
    end

    function hub.Spawn(fn, ...)
        local thread = task.spawn(fn, ...)
        hub._threads[#hub._threads + 1] = thread
        return thread
    end

    ----------------------------------------------------------------- UI boot
    local Fluent = loadstring(game:HttpGet(FLUENT_URL))()

    local SaveManager, InterfaceManager
    pcall(function() SaveManager      = loadstring(game:HttpGet(SAVEMGR_URL))() end)
    pcall(function() InterfaceManager = loadstring(game:HttpGet(INTERFACE_URL))() end)

    hub.Fluent = Fluent

    function hub.Notify(content, duration, title)
        Fluent:Notify({
            Title    = title or config.Name,
            Content  = tostring(content),
            Duration = duration or 4,
        })
    end

    local Window = Fluent:CreateWindow({
        Title       = config.Name .. " " .. (config.Version or ""),
        SubTitle    = hub.GameInfo.Name,
        TabWidth    = 160,
        Size        = UDim2.fromOffset(580, 460),
        Acrylic     = true,
        Theme       = "Dark",
        MinimizeKey = Enum.KeyCode.LeftControl,
    })
    hub.Window  = Window
    hub.Options = Fluent.Options
    hub.Tabs    = {}

    function hub.AddTab(title, icon)
        local tab = Window:AddTab({ Title = title, Icon = icon or "box" })
        hub.Tabs[title] = tab
        return tab
    end

    ----------------------------------------------------------------- unload
    function hub.Unload()
        if hub.Unloaded then return end
        hub.Unloaded = true

        for _, fn in ipairs(hub._cleanup) do pcall(fn) end
        for _, conn in ipairs(hub._conns) do pcall(function() conn:Disconnect() end) end
        for _, thread in ipairs(hub._threads) do pcall(task.cancel, thread) end

        pcall(function() Fluent:Destroy() end)
        genv.__ScriptHub = nil
    end

    genv.__ScriptHub = hub

    ----------------------------------------------------------------- modules
    local registry = HUB_REQUIRE("src/registry")
    local matched, universal = resolve(registry, hub.GameInfo)

    local function runEntry(entry)
        local tabTitle = entry.Name or "Script"
        local ctx = {
            Hub      = hub,
            Fluent   = Fluent,
            Window   = Window,
            Options  = Fluent.Options,
            GameInfo = hub.GameInfo,
            Entry    = entry,
            Tab      = hub.AddTab(tabTitle, entry.Icon or "play"),
            Notify   = hub.Notify,
            Connect  = hub.Connect,
            Spawn    = hub.Spawn,
            OnUnload = hub.OnUnload,
        }
        function ctx.IsAlive() return not hub.Unloaded end

        local ok, mod = pcall(HUB_REQUIRE, entry.Module)
        if not ok then
            ctx.Tab:AddParagraph({ Title = "Failed to download", Content = tostring(mod) })
            hub.Notify("Could not load " .. tabTitle, 6)
            return false
        end

        local ranOk, err = pcall(mod.Setup, ctx)
        if not ranOk then
            ctx.Tab:AddParagraph({ Title = "Script error", Content = tostring(err) })
            hub.Notify(tabTitle .. " errored: " .. tostring(err), 8)
            return false
        end

        hub._loaded[#hub._loaded + 1] = entry
        return true
    end

    for _, entry in ipairs(matched) do runEntry(entry) end
    for _, entry in ipairs(universal) do runEntry(entry) end

    ----------------------------------------------------------------- hub tab
    local HubTab = hub.AddTab("Hub", "settings")

    if #matched == 0 then
        HubTab:AddParagraph({
            Title   = "No script for this game (yet)",
            Content = ("%s\nPlaceId: %d\nGameId: %d\n\nSend the PlaceId over and it can be added to the registry.")
                :format(hub.GameInfo.Name, hub.GameInfo.PlaceId, hub.GameInfo.GameId),
        })
    else
        local names = {}
        for _, entry in ipairs(matched) do
            names[#names + 1] = ("%s  (matched by %s)"):format(entry.Name, entry._matchedBy or "?")
        end
        HubTab:AddParagraph({
            Title   = "Loaded for this game",
            Content = table.concat(names, "\n"),
        })
    end

    HubTab:AddParagraph({
        Title   = "Environment",
        Content = ("Game: %s\nPlaceId: %d\nGameId: %d\nExecutor: %s\nHub: %s %s")
            :format(hub.GameInfo.Name, hub.GameInfo.PlaceId, hub.GameInfo.GameId,
                    hub.Executor, config.Name, config.Version or ""),
    })

    HubTab:AddButton({
        Title       = "Copy PlaceId",
        Description = "Puts this game's PlaceId on your clipboard",
        Callback    = function()
            if setclipboard then
                setclipboard(tostring(hub.GameInfo.PlaceId))
                hub.Notify("PlaceId copied: " .. hub.GameInfo.PlaceId)
            else
                hub.Notify("This executor has no setclipboard - PlaceId is " .. hub.GameInfo.PlaceId, 8)
            end
        end,
    })

    HubTab:AddButton({
        Title       = "Rejoin",
        Description = "Teleport back into this place",
        Callback    = function()
            pcall(function()
                TeleportService:Teleport(game.PlaceId, Players.LocalPlayer)
            end)
        end,
    })

    HubTab:AddButton({
        Title       = "Unload hub",
        Description = "Closes the UI and stops every loaded script",
        Callback    = function() hub.Unload() end,
    })

    -- Fluent's own config/interface panels, if the addons downloaded.
    pcall(function()
        InterfaceManager:SetLibrary(Fluent)
        SaveManager:SetLibrary(Fluent)
        SaveManager:IgnoreThemeSettings()
        SaveManager:SetIgnoreIndexes({})
        InterfaceManager:SetFolder(config.Name)
        SaveManager:SetFolder(config.Name .. "/" .. tostring(hub.GameInfo.PlaceId))
        InterfaceManager:BuildInterfaceSection(HubTab)
        SaveManager:BuildConfigSection(HubTab)
        SaveManager:LoadAutoloadConfig()
    end)

    Window:SelectTab(1)

    if #matched == 0 then
        hub.Notify("No script for " .. hub.GameInfo.Name .. " yet", 6)
    else
        hub.Notify(("Loaded %d script%s for %s"):format(
            #hub._loaded, #hub._loaded == 1 and "" or "s", hub.GameInfo.Name), 5)
    end

    return hub
end

return Core
]=]
__sources["src/registry"] = [=[
--[[
    Script Hub - registry
    =====================
    The only file you edit when adding a game.

    Entry fields
    ------------
    Name        required  tab title + display name
    Module      required  path passed to HUB_REQUIRE, no .lua extension
    PlaceIds    list of place ids this script is for (most specific match)
    GameIds     list of universe ids - catches every place in a universe
                (lobby + maps), use when a game teleports players around
    NameMatch   lowercase substring of the marketplace name; a safety net so
                a script still loads before you have written the id down
    Universal   true = always load, in every game
    Icon        lucide icon name for the tab
    Author      credit shown in the Hub tab
    Description free text

    Matching order is PlaceIds -> GameIds -> NameMatch. Several entries may
    match at once; each one gets its own tab.
]]

return {
    {
        Name        = "Spelling Race",
        Module      = "src/scripts/spelling_race",
        -- TODO: paste the real id here (Hub tab -> Copy PlaceId while in game)
        PlaceIds    = {},
        GameIds     = {},
        NameMatch   = "spelling race",
        Icon        = "book-a",
        Author      = "light2light (deobfuscated)",
        Description = "Decodes the round's word from the hidden attribute and auto-submits it.",
    },

    {
        Name        = "Finish The Word",
        Module      = "src/scripts/finish_the_word",
        -- listed as both so it matches whether 91704854174760 is the place id
        -- or the universe id; either one is enough
        PlaceIds    = { 91704854174760 },
        GameIds     = { 91704854174760 },
        NameMatch   = "finish the word",
        Icon        = "spell-check",
        Author      = "unknown (deobfuscated)",
        Description = "Reads the game's word list from memory and finishes the prompt.",
    },

    {
        Name        = "Universal",
        Module      = "src/scripts/universal",
        Universal   = true,
        Icon        = "globe",
        Author      = "hub",
        Description = "Server tools that work anywhere.",
    },

    --[[  template - copy this block for each new script

    {
        Name        = "Game Name",
        Module      = "src/scripts/game_name",
        PlaceIds    = { 1234567890 },
        GameIds     = {},
        NameMatch   = "game name",
        Icon        = "play",
        Author      = "original author",
        Description = "what it does",
    },

    ]]
}
]=]
__sources["src/scripts/finish_the_word"] = [=[
--[[
    Finish The Word - word solver / auto answer
    ===========================================
    Recovered from "finishtheword.lua.txt" (Luau VM obfuscator, two nested
    stages) and rewritten against the hub module contract.

    How the original talks to the game -- all of this is reproduced below:

      * it scans the garbage collector for the game's networking table, which
        is the one carrying `remoteFire` / `remoteConnect` / `fire` / `ping`,
        and drives the round with:
              net.fire("tryKeystroke", "A")   -- one letter at a time
              net.fire("tryAnswer")           -- submit
      * a turn is live when LocalPlayer:GetAttribute("IsTurn") is true;
        the question itself is another gc table carrying `QuestionLabel` and
        either `RequiredLetter` (a prefix to extend) or `Choices` (pick one)
      * words come from the game's own list: a gc string containing
        "whitelistedFtwWords", newline separated, `^[a-z]+$` only

    Deliberately NOT reproduced: the original also downloaded its UI library,
    a save manager and a version file from a third-party domain
    (ancestrychanged.com) and executed them with loadstring, and it ran an
    extra remote payload on some executors. The hub supplies the UI instead,
    so none of that remote code is fetched. See README.
]]

local M = {}

local KEYBOARD = {
    -- x = column, y = row, h = hand; used for the humanised typing delays
    q = { x = 0, y = 0, h = 1 }, w = { x = 1, y = 0, h = 1 }, e = { x = 2, y = 0, h = 1 },
    r = { x = 3, y = 0, h = 1 }, t = { x = 4, y = 0, h = 1 }, y = { x = 5, y = 0, h = 2 },
    u = { x = 6, y = 0, h = 2 }, i = { x = 7, y = 0, h = 2 }, o = { x = 8, y = 0, h = 2 },
    p = { x = 9, y = 0, h = 2 },
    a = { x = 0, y = 1, h = 1 }, s = { x = 1, y = 1, h = 1 }, d = { x = 2, y = 1, h = 1 },
    f = { x = 3, y = 1, h = 1 }, g = { x = 4, y = 1, h = 1 }, h = { x = 5, y = 1, h = 2 },
    j = { x = 6, y = 1, h = 2 }, k = { x = 7, y = 1, h = 2 }, l = { x = 8, y = 1, h = 2 },
    z = { x = 0, y = 2, h = 1 }, x = { x = 1, y = 2, h = 1 }, c = { x = 2, y = 2, h = 1 },
    v = { x = 3, y = 2, h = 1 }, b = { x = 4, y = 2, h = 1 }, n = { x = 5, y = 2, h = 2 },
    m = { x = 6, y = 2, h = 2 },
}

function M.Setup(ctx)
    local Players = game:GetService("Players")
    local LocalPlayer = Players.LocalPlayer

    ------------------------------------------------------------------ state
    local settings = {
        autoAnswer   = false,
        autoChoose   = false,
        autoLearn    = true,
        humanType    = true,
        instant      = false,
        removeUsed   = true,
        showWhite    = true,
        endsWith     = "",
        suggestCount = 30,
        suggestSort  = "Shortest",
        answerDelay  = 0.8,
        typeDelay    = 0.12,
    }

    local words       = {}   -- [firstLetter] = { word, ... } sorted by length asc
    local known       = {}   -- [word] = true
    local rank        = {}   -- [word] = position in the source list ("most common")
    local used        = {}   -- [word] = true, cleared per round
    local blacklist   = {}
    local whitelist   = {}
    local wordCount   = 0
    local turnToken   = 0    -- bumped whenever the turn changes; cancels typing

    ------------------------------------------------------------- word store
    local function addWord(word)
        if known[word] then return end
        local bucket = words[word:sub(1, 1)]
        if not bucket then
            bucket = {}
            words[word:sub(1, 1)] = bucket
        end
        -- keep each bucket sorted by length, shortest first
        local pos = #bucket + 1
        for i, existing in ipairs(bucket) do
            if #existing > #word then
                pos = i
                break
            end
        end
        table.insert(bucket, pos, word)
        known[word] = true
        wordCount = wordCount + 1
    end

    -- `ranked` lists are in frequency order, so their line number doubles as
    -- the "most common" rank. Alphabetical lists must not set it.
    local function ingest(text, ranked)
        local added = 0
        local index = 0
        for line in tostring(text):gmatch("[^\r\n]+") do
            index = index + 1
            line = line:lower():match("^%s*(%a+)%s*$") or ""
            if #line > 0 then
                if ranked and rank[line] == nil then rank[line] = index end
                if not known[line] then
                    addWord(line)
                    added = added + 1
                end
            end
        end
        return added
    end

    -- The game keeps its own dictionary in memory; find it the way the
    -- original did, by looking for a string that mentions whitelistedFtwWords.
    local function loadGameWords()
        if not getgc then return 0 end
        local added = 0
        for _, object in ipairs(getgc(true)) do
            if type(object) == "string" and object:find("whitelistedFtwWords", 1, true) then
                added = added + ingest(object)
            end
        end
        return added
    end

    ------------------------------------------------------- online dictionary
    -- Fetched when the game's own list cannot be found in memory. The first
    -- list is frequency ordered, so it also supplies the "Most common" ranking.
    local WORD_SOURCES = {
        { name = "common 10k",
          ranked = true,
          url = "https://raw.githubusercontent.com/first20hours/google-10000-english/master/google-10000-english-usa.txt" },
        { name = "popular 25k",
          url = "https://raw.githubusercontent.com/dolph/dictionary/master/popular.txt" },
    }

    local FULL_DICTIONARY = {
        name = "full dictionary (~4MB)",
        url = "https://raw.githubusercontent.com/dwyl/english-words/master/words_alpha.txt",
    }

    local function httpGet(url)
        -- `request` keeps a status code, so try it first; HttpGet is the fallback
        local requester = (syn and syn.request) or http_request or request
        if requester then
            local ok, response = pcall(requester, { Url = url, Method = "GET" })
            if ok and type(response) == "table" and response.Body
                and (response.StatusCode == 200 or response.StatusCode == nil) then
                return response.Body
            end
        end
        local ok, body = pcall(function() return game:HttpGet(url) end)
        if ok and type(body) == "string" and #body > 0 then return body end
        return nil
    end

    local function downloadList(source)
        local body = httpGet(source.url)
        if not body then
            ctx.Notify("could not download " .. source.name, 5, "Finish The Word")
            return 0
        end
        return ingest(body, source.ranked)
    end

    local function downloadDictionary(includeFull)
        local added = 0
        for _, source in ipairs(WORD_SOURCES) do
            added = added + downloadList(source)
        end
        if includeFull then
            added = added + downloadList(FULL_DICTIONARY)
        end
        return added
    end

    ------------------------------------------------------------ game lookup
    local network
    local function findNetwork()
        if network then return network end
        if not getgc then return nil end
        for _, object in ipairs(getgc(true)) do
            if type(object) == "table"
                and rawget(object, "remoteFire") and rawget(object, "remoteConnect")
                and rawget(object, "fire") and rawget(object, "ping") then
                network = object
                return network
            end
        end
        return nil
    end

    local function findQuestion()
        if not getgc then return nil end
        for _, object in ipairs(getgc(true)) do
            if type(object) == "table" and rawget(object, "QuestionLabel")
                and (rawget(object, "RequiredLetter") or rawget(object, "Choices")) then
                return object
            end
        end
        return nil
    end

    -- Some builds of the game do not set this attribute at all; when it is
    -- absent we fall back to "a prompt is on screen" as the trigger.
    local turnAttributeMissing = false

    local function isMyTurn()
        local ok, value = pcall(function()
            return LocalPlayer:GetAttribute("IsTurn")
        end)
        if not ok or value == nil then
            turnAttributeMissing = true
            return false
        end
        turnAttributeMissing = false
        return value == true
    end

    ------------------------------------------------------------- searching
    local function candidates(prefix, limit, includeUsed, includeBlacklisted)
        local out = {}
        local bucket = words[prefix:sub(1, 1)]
        if not bucket then return out end
        for _, word in ipairs(bucket) do
            if #word >= #prefix and word:sub(1, #prefix) == prefix
                and (includeBlacklisted or not blacklist[word])
                and (includeUsed or not used[word]) then
                out[#out + 1] = word
                if limit and #out >= limit then break end
            end
        end
        return out
    end

    local function comparator()
        local mode = settings.suggestSort
        if mode == "Shortest" then
            return function(a, b)
                if #a ~= #b then return #a < #b end
                return a < b
            end
        elseif mode == "Longest" then
            return function(a, b)
                if #a ~= #b then return #a > #b end
                return a < b
            end
        elseif mode == "a-Z" then
            return function(a, b) return a < b end
        elseif mode == "Z-a" then
            return function(a, b) return a > b end
        elseif mode == "Most common" then
            return function(a, b)
                local ra, rb = rank[a] or math.huge, rank[b] or math.huge
                if ra ~= rb then return ra < rb end
                return a < b
            end
        end
        return nil
    end

    -- returns { { word = "...", check = true|nil }, ... }
    local function suggestions(prefix, includeUsed, includeBlacklisted)
        local list = candidates(prefix, nil, includeUsed, includeBlacklisted)

        local suffix = settings.endsWith:lower()
        if #suffix > 0 then
            local filtered = {}
            for _, word in ipairs(list) do
                if #word >= #suffix and word:sub(-#suffix) == suffix then
                    filtered[#filtered + 1] = word
                end
            end
            list = filtered
        end

        local cmp = comparator()
        local out = {}
        if settings.showWhite then
            local white, rest = {}, {}
            for _, word in ipairs(list) do
                if whitelist[word] then white[#white + 1] = word else rest[#rest + 1] = word end
            end
            if cmp then
                table.sort(white, cmp)
                table.sort(rest, cmp)
            end
            for _, word in ipairs(white) do out[#out + 1] = { word = word, check = true } end
            for _, word in ipairs(rest) do out[#out + 1] = { word = word } end
        else
            if cmp then table.sort(list, cmp) end
            for _, word in ipairs(list) do out[#out + 1] = { word = word } end
        end
        return out
    end

    local function bestWord(prefix)
        local list = suggestions(prefix, false, false)
        if #list == 0 and #settings.endsWith > 0 then
            -- the suffix filter starved the search: drop it and retry, as the
            -- original does
            settings.endsWith = ""
            list = suggestions(prefix, false, false)
        end
        return list[1] and list[1].word or nil
    end

    ------------------------------------------------------- humanised typing
    -- Per-key delays weighted by keyboard travel, normalised so the whole word
    -- takes about (#keys * TypeDelay) seconds.
    local function typingDelays(word, from)
        local weights, total = {}, 0
        local previous = word:sub(from - 1, from - 1)

        for i = from, #word do
            local char = word:sub(i, i)
            local weight = 1.2
            local a, b = KEYBOARD[char], KEYBOARD[previous]
            if a and b then
                if char == previous then
                    weight = 0.2
                elseif a.h ~= b.h then
                    weight = 0.5
                else
                    weight = 0.8 + math.sqrt((a.x - b.x) ^ 2 + (a.y - b.y) ^ 2) * 0.3
                end
            end
            weight = weight * math.random(90, 110) / 100
            weights[#weights + 1] = weight
            total = total + weight
            previous = char
        end

        local target = #weights * settings.typeDelay
        if #weights < 6 then
            target = math.clamp(target, 0.1, 0.7)
        else
            target = math.clamp(target, 0.28, 2.5)
        end
        for i, weight in ipairs(weights) do
            weights[i] = weight / total * target
        end
        return weights
    end

    ----------------------------------------------------------------- answer
    local currentPrefix = ""

    local function answerWith(word, prefix)
        local net = findNetwork()
        if not net then
            ctx.Notify("Could not find the game's network module", 6, "Finish The Word")
            return
        end

        turnToken = turnToken + 1
        local token = turnToken
        used[word] = true

        local delays
        if settings.humanType and not settings.instant then
            delays = typingDelays(word, #prefix + 1)
        end

        for i = #prefix + 1, #word do
            if token ~= turnToken or not ctx.IsAlive() then return end
            net.fire("tryKeystroke", word:sub(i, i):upper())
            if not settings.instant then
                task.wait(delays and delays[i - #prefix] or settings.typeDelay)
            end
        end

        if token ~= turnToken or not ctx.IsAlive() then return end
        if not settings.instant then
            task.wait(settings.answerDelay)
        end
        if token ~= turnToken or not ctx.IsAlive() then return end

        net.fire("tryAnswer")
        if settings.autoLearn then addWord(word) end
    end

    ------------------------------------------------------------ suggestions UI
    local suggestionBox
    local statusBox

    -- Read the toggles/sliders straight off the UI every tick. Relying only on
    -- OnChanged misses values restored by a saved config or set with SetValue,
    -- which is the usual reason "auto answer" looks switched on but does nothing.
    local OPTION_MAP = {
        FTW_AutoAnswer      = "autoAnswer",
        FTW_AutoChoose      = "autoChoose",
        FTW_InstantAnswer   = "instant",
        FTW_HumanType       = "humanType",
        FTW_AutoLearn       = "autoLearn",
        FTW_RemoveUsed      = "removeUsed",
        FTW_ShowWhitelisted = "showWhite",
        FTW_AnswerDelay     = "answerDelay",
        FTW_TypeDelay       = "typeDelay",
        FTW_SuggestCount    = "suggestCount",
        FTW_SuggestSort     = "suggestSort",
        FTW_EndsWith        = "endsWith",
        FTW_WordEntry       = "wordEntry",
    }

    local function syncOptions()
        local options = ctx.Options
        if not options then return end
        for id, key in pairs(OPTION_MAP) do
            local option = options[id]
            if option ~= nil then
                local ok, value = pcall(function() return option.Value end)
                if ok and value ~= nil then
                    if key == "endsWith" or key == "wordEntry" or key == "suggestSort" then
                        settings[key] = tostring(value)
                    else
                        settings[key] = value
                    end
                end
            end
        end
    end

    local function updateStatus(question, turn)
        if not statusBox then return end
        local net = findNetwork()
        local prompt = "-"
        if question then
            prompt = question.Choices and "choices" or tostring(question.RequiredLetter)
        end
        pcall(function()
            statusBox:SetDesc(("words: %d   network: %s   prompt: %s   IsTurn: %s%s")
                :format(wordCount,
                        net and "found" or "NOT FOUND",
                        prompt,
                        turn and "true" or "false",
                        turnAttributeMissing and " (attribute missing - answering on prompt)" or ""))
        end)
    end

    local function showSuggestions(lines)
        if not suggestionBox then return end
        pcall(function()
            suggestionBox:SetDesc(#lines > 0 and table.concat(lines, "\n") or "-")
        end)
    end

    local function refresh(question)
        if wordCount == 0 then
            showSuggestions({ "words still downloading..." })
            return
        end

        if question.Choices then
            local lines = {}
            for _, choice in ipairs(question.Choices) do
                local letter = tostring(choice):lower()
                lines[#lines + 1] = ("%s: %d words"):format(tostring(choice):upper(),
                    #candidates(letter, nil, true, false))
            end
            showSuggestions(lines)
            return
        end

        if not question.RequiredLetter then return end
        local prefix = tostring(question.RequiredLetter):lower()
        currentPrefix = prefix

        local list = suggestions(prefix, not settings.removeUsed, false)
        local lines = {}
        for _, entry in ipairs(list) do
            if #lines >= settings.suggestCount then break end
            lines[#lines + 1] = (entry.check and "* " or "") .. entry.word
        end

        if #lines > 0 then
            showSuggestions(lines)
        elseif #settings.endsWith > 0 then
            showSuggestions({ ('no words ending in "%s"'):format(settings.endsWith:lower()) })
        else
            showSuggestions({ ('no words for "%s"'):format(prefix) })
        end
    end

    ------------------------------------------------------------------ turn
    local answering = false
    local answeredPrompt = nil   -- the prompt we already acted on

    local function handleTurn(question)
        if question.Choices then
            if not settings.autoChoose then return end
            -- pick the choice letter with the most available words
            local best, bestCount = nil, -1
            for _, choice in ipairs(question.Choices) do
                local letter = tostring(choice):lower()
                local count = #candidates(letter, nil, true, false)
                if count > bestCount then
                    best, bestCount = choice, count
                end
            end
            if best then
                local net = findNetwork()
                if net then net.fire("tryKeystroke", tostring(best):upper()) end
            end
            return
        end

        if not settings.autoAnswer then return end
        if not question.RequiredLetter then return end

        local prefix = tostring(question.RequiredLetter):lower()
        local word = bestWord(prefix)
        if not word then
            ctx.Notify(('no words left for "%s"'):format(prefix), 4, "Finish The Word")
            return
        end
        answerWith(word, prefix)
    end

    -- One prompt = one answer. The turn attribute is not reliable on its own
    -- (it can flip after the prompt appears, or not exist at all on some
    -- versions), so the prompt text itself is what gates a new answer.
    local function promptKey(question)
        if question.Choices then
            local parts = {}
            for _, choice in ipairs(question.Choices) do parts[#parts + 1] = tostring(choice) end
            return "choices:" .. table.concat(parts, ",")
        end
        return "prefix:" .. tostring(question.RequiredLetter)
    end

    ------------------------------------------------------------------- UI
    ctx.Tab:AddParagraph({
        Title   = "Finish The Word",
        Content = "Reads the game's own word list out of memory and finishes the prompt. "
               .. "Auto answer types the word key by key, so Typing delay / Humanized "
               .. "typing decide how fast it looks.",
    })

    ctx.Tab:AddToggle("FTW_AutoAnswer", { Title = "Auto answer", Default = false })
        :OnChanged(function(value) settings.autoAnswer = value end)

    ctx.Tab:AddToggle("FTW_AutoChoose", { Title = "Auto pick choice letter", Default = false })
        :OnChanged(function(value) settings.autoChoose = value end)

    ctx.Tab:AddToggle("FTW_InstantAnswer", { Title = "Instant (no typing delays)", Default = false })
        :OnChanged(function(value) settings.instant = value end)

    ctx.Tab:AddToggle("FTW_HumanType", { Title = "Humanized typing", Default = true })
        :OnChanged(function(value) settings.humanType = value end)

    ctx.Tab:AddToggle("FTW_AutoLearn", { Title = "Auto-learn words", Default = true })
        :OnChanged(function(value) settings.autoLearn = value end)

    ctx.Tab:AddSlider("FTW_AnswerDelay", {
        Title = "Delay before submitting", Default = 0.8, Min = 0, Max = 5, Rounding = 1,
    }):OnChanged(function(value) settings.answerDelay = value end)

    ctx.Tab:AddSlider("FTW_TypeDelay", {
        Title = "Typing delay", Default = 0.12, Min = 0.05, Max = 0.5, Rounding = 2,
    }):OnChanged(function(value) settings.typeDelay = value end)

    ctx.Tab:AddToggle("FTW_RemoveUsed", { Title = "Remove used words", Default = true })
        :OnChanged(function(value) settings.removeUsed = value end)

    ctx.Tab:AddToggle("FTW_ShowWhitelisted", { Title = "Show whitelisted words", Default = true })
        :OnChanged(function(value) settings.showWhite = value end)

    ctx.Tab:AddSlider("FTW_SuggestCount", {
        Title = "Suggestion count", Default = 30, Min = 1, Max = 100, Rounding = 0,
    }):OnChanged(function(value) settings.suggestCount = value end)

    ctx.Tab:AddDropdown("FTW_SuggestSort", {
        Title = "Sort suggestions",
        Values = { "Shortest", "Longest", "a-Z", "Z-a", "Most common" },
        Default = 1,
    }):OnChanged(function(value) settings.suggestSort = tostring(value) end)

    ctx.Tab:AddInput("FTW_EndsWith", {
        Title = "Word ends with", Default = "", Placeholder = "suffix",
    }):OnChanged(function(value) settings.endsWith = tostring(value or "") end)

    ctx.Tab:AddInput("FTW_WordEntry", {
        Title = "Word", Default = "", Placeholder = "type a word",
    }):OnChanged(function(value) settings.wordEntry = tostring(value or ""):lower() end)

    local function entry()
        local word = tostring(settings.wordEntry or ""):lower():match("^[a-z]+$")
        if not word then
            ctx.Notify("Type a word (a-z only) in the Word box first", 4, "Finish The Word")
        end
        return word
    end

    ctx.Tab:AddButton({
        Title = "Add to whitelist",
        Callback = function()
            local word = entry()
            if word then
                whitelist[word] = true
                addWord(word)
                ctx.Notify("whitelisted " .. word, 3, "Finish The Word")
            end
        end,
    })

    ctx.Tab:AddButton({
        Title = "Remove from whitelist",
        Callback = function()
            local word = entry()
            if word then
                whitelist[word] = nil
                ctx.Notify("un-whitelisted " .. word, 3, "Finish The Word")
            end
        end,
    })

    ctx.Tab:AddButton({
        Title = "Add to blacklist",
        Callback = function()
            local word = entry()
            if word then
                blacklist[word] = true
                ctx.Notify("blacklisted " .. word, 3, "Finish The Word")
            end
        end,
    })

    ctx.Tab:AddButton({
        Title = "Remove from blacklist",
        Callback = function()
            local word = entry()
            if word then
                blacklist[word] = nil
                ctx.Notify("un-blacklisted " .. word, 3, "Finish The Word")
            end
        end,
    })

    ctx.Tab:AddButton({
        Title       = "Answer now",
        Description = "Solve the current prompt once, ignoring Auto answer",
        Callback    = function()
            ctx.Spawn(function()
                local question = findQuestion()
                if not question or not question.RequiredLetter then
                    ctx.Notify("No prompt on screen right now", 4, "Finish The Word")
                    return
                end
                local prefix = tostring(question.RequiredLetter):lower()
                local word = bestWord(prefix)
                if not word then
                    ctx.Notify(('no words left for "%s"'):format(prefix), 4, "Finish The Word")
                    return
                end
                answerWith(word, prefix)
            end)
        end,
    })

    ctx.Tab:AddButton({
        Title       = "Reload word list",
        Description = "Re-read the game's dictionary out of memory",
        Callback    = function()
            local added = loadGameWords()
            ctx.Notify(("loaded %d words (%d total)"):format(added, wordCount), 4, "Finish The Word")
        end,
    })

    ctx.Tab:AddButton({
        Title       = "Download dictionary",
        Description = "~35k words incl. a frequency list (for 'Most common')",
        Callback    = function()
            ctx.Spawn(function()
                ctx.Notify("downloading word lists...", 3, "Finish The Word")
                local added = downloadDictionary(false)
                ctx.Notify(("downloaded %d words (%d total)"):format(added, wordCount), 5,
                    "Finish The Word")
            end)
        end,
    })

    ctx.Tab:AddButton({
        Title       = "Download full dictionary",
        Description = "~370k words, a few MB - slower, much better coverage",
        Callback    = function()
            ctx.Spawn(function()
                ctx.Notify("downloading full dictionary, this takes a moment...", 5,
                    "Finish The Word")
                local added = downloadDictionary(true)
                ctx.Notify(("downloaded %d words (%d total)"):format(added, wordCount), 5,
                    "Finish The Word")
            end)
        end,
    })

    statusBox = ctx.Tab:AddParagraph({ Title = "Status", Content = "-" })
    suggestionBox = ctx.Tab:AddParagraph({ Title = "Suggestions", Content = "-" })

    ------------------------------------------------------------------ run
    if not getgc then
        ctx.Tab:AddParagraph({
            Title   = "Executor too limited",
            Content = "This script needs getgc to read the game's word list and network module.",
        })
        return
    end

    ctx.Spawn(function()
        local added = loadGameWords()
        if added > 0 then
            ctx.Notify(("loaded %d words from the game"):format(added), 5, "Finish The Word")
        else
            -- nothing in memory (round not started, or a build that keeps the
            -- list server-side): fall back to the online lists
            ctx.Notify("no word list in memory - downloading one...", 4, "Finish The Word")
            added = downloadDictionary(false)
            ctx.Notify(added > 0 and ("downloaded %d words"):format(added)
                or "could not load any word list - check your executor's HTTP support",
                5, "Finish The Word")
        end
    end)

    -- Main loop: watch for a prompt, answer it once, keep the panel current.
    ctx.Spawn(function()
        local wasTurn = false

        while ctx.IsAlive() do
            syncOptions()

            local turn = isMyTurn()
            if turn ~= wasTurn then
                if turn then used = {} end   -- new turn: used words reset
                answeredPrompt = nil
                wasTurn = turn
            end

            local question = findQuestion()
            if question then
                pcall(refresh, question)

                local key = promptKey(question)
                if key ~= answeredPrompt and not answering
                    and (turn or turnAttributeMissing) then
                    answeredPrompt = key
                    answering = true
                    local ok, err = pcall(handleTurn, question)
                    answering = false
                    if not ok then
                        ctx.Notify("error: " .. tostring(err), 6, "Finish The Word")
                    end
                end
            end

            updateStatus(question, turn)
            task.wait(0.2)
        end
    end)
end

return M
]=]
__sources["src/scripts/spelling_race"] = [=[
--[[
    Spelling Race - auto spell
    ==========================
    Deobfuscated from "auto spell keyless.txt" (WeAreDevs obfuscator v1.0.0,
    original by light2light) and adapted to the hub module contract.

    How the game hides the answer, innermost first:
      1. the word is turned into ASCII codes
      2. each code has its DIGITS REVERSED          ("a" = 97 -> "79")
      3. codes are joined with commas
      4. every byte is XOR'd with a repeating key:  "1144" .. PlaceId .. "00552002"
      5. the result lives in the "Color" attribute of the Texture under a
         scenery part in workspace.Floors2
      6. Lighting.Bloom.Sky.StarCount is a per-round offset subtracted from
         every character code

    If the payload is missing or unusable the script falls back to the first
    non-empty AnswerControl.Answer1..4 value, exactly like the original.
]]

local M = {}

local HIDDEN_PART = "Part +R2107+ +R21+ +R21+ +R21+ +R21+ +R21+ +R21+ +R21+ +R21+ +R22+2"

function M.Setup(ctx)
    local ReplicatedStorage = game:GetService("ReplicatedStorage")

    local RoundControl = ReplicatedStorage:WaitForChild("RoundControlFolder", 10)
    local Remotes      = ReplicatedStorage:WaitForChild("Remotes", 10)
    if not (RoundControl and Remotes) then
        ctx.Tab:AddParagraph({
            Title   = "Not in a round yet",
            Content = "RoundControlFolder / Remotes were not found. Rejoin once a match is running and re-execute.",
        })
        return
    end

    local TopicControl  = RoundControl:WaitForChild("TopicControl", 10)
    local AnswerControl = RoundControl:WaitForChild("AnswerControl", 10)
    local SubmitAnswer  = Remotes:WaitForChild("SubmitAnswerRemote", 10)
    local TopicDesc     = TopicControl and TopicControl:WaitForChild("TopicDesc", 10)

    if not (TopicDesc and AnswerControl and SubmitAnswer) then
        ctx.Tab:AddParagraph({
            Title   = "Game layout changed",
            Content = "TopicDesc / AnswerControl / SubmitAnswerRemote missing - the script needs updating.",
        })
        return
    end

    --------------------------------------------------------------- settings
    local settings = {
        autoSpell   = true,
        answerDelay = 2.2,
        randomize   = true,
        notify      = true,
    }

    local function say(text, duration)
        if settings.notify then
            ctx.Notify(text, duration or 3, "Spelling Race")
        end
    end

    --------------------------------------------------------------- decoding
    local function readPayload()
        local floors = workspace:FindFirstChild("Floors2")
        if not floors then return nil end

        local part = floors:FindFirstChild(HIDDEN_PART)
        if not part then return nil end

        local texture = part:FindFirstChildOfClass("Texture")
        if not texture then return nil end

        return texture:GetAttribute("Color")
    end

    local function decodeWord()
        local payload = readPayload()
        if not payload or payload == "" then return nil end

        -- undo the XOR; bytes that come out as letters are corrupt and
        -- collapse into the "," separator so they drop out of the split
        local key   = "1144" .. game.PlaceId .. "00552002"
        local plain = {}
        for i = 1, #payload do
            local b = bit32.bxor(payload:byte(i), key:byte((i - 1) % #key + 1))
            if (b >= 65 and b <= 90) or (b >= 97 and b <= 122) then
                b = 44
            end
            plain[i] = string.char(b)
        end

        local offset = 0
        pcall(function()
            offset = game.Lighting.Bloom.Sky.StarCount
        end)

        local word = ""
        for _, chunk in ipairs(string.split(table.concat(plain), ",")) do
            local code = tonumber(string.reverse(chunk))
            if code then
                code = code - offset
                if code >= 32 and code <= 126 then
                    word = word .. string.char(code)
                end
            end
        end

        if word ~= "" then return word end
        return nil
    end

    local function fallbackAnswer()
        for i = 1, 4 do
            local answer = AnswerControl:FindFirstChild("Answer" .. i)
            local value  = answer and answer.Value or ""
            if value ~= "" then return value end
        end
        return ""
    end

    --------------------------------------------------------------- submitting
    local function submit(word, elapsed)
        -- the trailing two spaces are part of what the original sends
        local ok, result = pcall(function()
            return SubmitAnswer:InvokeServer(word .. "  ", "keyboard", nil, elapsed)
        end)
        if not ok then
            say("Submit failed: " .. tostring(result), 6)
            return nil
        end

        if result then
            if result.correct then
                say("Correct! +" .. tostring(result.score))
            elseif result.closeAnswer then
                say("Close! +" .. tostring(result.score))
            else
                say("Wrong: " .. tostring(result.correctAnswer or "?"))
            end
        end
        return result
    end

    local function currentWord()
        local word
        for _ = 1, 5 do
            if not ctx.IsAlive() then return nil end
            word = decodeWord()
            if word then return word end
            task.wait(0.5)
        end
        return nil
    end

    local busy = false

    local function solveRound()
        if busy or not ctx.IsAlive() or not settings.autoSpell then return end
        busy = true

        say("Loading word...")
        task.wait(1)

        local word = currentWord() or fallbackAnswer()
        if word == "" or not ctx.IsAlive() then
            busy = false
            return
        end

        say("Word: " .. word)

        local delay = settings.answerDelay
        if settings.randomize then
            delay = delay + (math.random() - 0.5) -- +/- 0.5s jitter
        end
        task.wait(delay)

        if ctx.IsAlive() and settings.autoSpell then
            say("Spelling...")
            submit(word, delay - 0.7)
        end
        busy = false
    end

    --------------------------------------------------------------- interface
    ctx.Tab:AddParagraph({
        Title   = "Spelling Race",
        Content = "Reads the round's word straight out of the game and answers it. "
               .. "Answer Time 2.2 with Randomize on looks the most human.",
    })

    local autoToggle = ctx.Tab:AddToggle("SpellingRace_AutoSpell", {
        Title   = "Auto Spell",
        Default = true,
    })
    autoToggle:OnChanged(function(value)
        settings.autoSpell = value
    end)

    ctx.Tab:AddSlider("SpellingRace_AnswerDelay", {
        Title       = "Answer Time",
        Description = "Delay before answering (seconds)",
        Default     = 2.2,
        Min         = 0.1,
        Max         = 5,
        Rounding    = 1,
        Callback    = function(value)
            settings.answerDelay = value
        end,
    })

    local randomToggle = ctx.Tab:AddToggle("SpellingRace_Randomize", {
        Title       = "Randomize Time",
        Description = "Adds up to +/- 0.5s of jitter",
        Default     = true,
    })
    randomToggle:OnChanged(function(value)
        settings.randomize = value
    end)

    local notifyToggle = ctx.Tab:AddToggle("SpellingRace_Notifications", {
        Title   = "Notifications",
        Default = true,
    })
    notifyToggle:OnChanged(function(value)
        settings.notify = value
    end)

    ctx.Tab:AddButton({
        Title       = "Spell Now",
        Description = "Answer the current word immediately",
        Callback    = function()
            ctx.Spawn(function()
                local word = decodeWord() or fallbackAnswer()
                if word == "" then
                    ctx.Notify("No word available yet", 4, "Spelling Race")
                    return
                end
                ctx.Notify("Spelling now...", 3, "Spelling Race")
                submit(word, 0.1)
            end)
        end,
    })

    ctx.Tab:AddButton({
        Title       = "Show decoded word",
        Description = "Peek at the answer without submitting",
        Callback    = function()
            local word = decodeWord()
            ctx.Notify(word and ("Word: " .. word) or "Payload not readable right now", 5, "Spelling Race")
        end,
    })

    --------------------------------------------------------------- run
    ctx.Connect(TopicDesc:GetPropertyChangedSignal("Value"), function()
        if TopicDesc.Value ~= "" then
            ctx.Spawn(solveRound)
        end
    end)

    if TopicDesc.Value ~= "" then
        ctx.Spawn(solveRound)
    end
end

return M
]=]
__sources["src/scripts/universal"] = [=[
--[[
    Universal tools
    ===============
    Loaded in every game (Universal = true in the registry). Keep this file
    for things that never depend on a specific place: server hopping, rejoin,
    FPS/ping readouts, character conveniences.

    It also doubles as the reference implementation of the module contract:
      Setup(ctx) with ctx.Tab / ctx.Notify / ctx.Connect / ctx.Spawn /
      ctx.OnUnload / ctx.IsAlive.
]]

local M = {}

function M.Setup(ctx)
    local Players         = game:GetService("Players")
    local TeleportService = game:GetService("TeleportService")
    local HttpService     = game:GetService("HttpService")
    local RunService      = game:GetService("RunService")
    local StarterGui      = game:GetService("StarterGui")

    local LocalPlayer = Players.LocalPlayer

    ctx.Tab:AddParagraph({
        Title   = "Server",
        Content = "Works in any game.",
    })

    ctx.Tab:AddButton({
        Title       = "Rejoin",
        Description = "Teleport back into this place",
        Callback    = function()
            pcall(function()
                TeleportService:Teleport(game.PlaceId, LocalPlayer)
            end)
        end,
    })

    ctx.Tab:AddButton({
        Title       = "Server hop",
        Description = "Jump to another public server of this game",
        Callback    = function()
            ctx.Spawn(function()
                local url = ("https://games.roblox.com/v1/games/%d/servers/Public?sortOrder=Asc&limit=100")
                    :format(game.PlaceId)

                local ok, body = pcall(function()
                    return game:HttpGet(url)
                end)
                if not ok then
                    ctx.Notify("Server list request failed", 5)
                    return
                end

                local decoded
                ok, decoded = pcall(function() return HttpService:JSONDecode(body) end)
                if not ok or type(decoded) ~= "table" or not decoded.data then
                    ctx.Notify("Could not read the server list", 5)
                    return
                end

                for _, server in ipairs(decoded.data) do
                    if server.playing and server.maxPlayers
                        and server.playing < server.maxPlayers
                        and server.id ~= game.JobId then
                        ctx.Notify("Hopping...", 4)
                        TeleportService:TeleportToPlaceInstance(game.PlaceId, server.id, LocalPlayer)
                        return
                    end
                end

                ctx.Notify("No other server with room", 5)
            end)
        end,
    })

    ctx.Tab:AddButton({
        Title       = "Copy JobId",
        Description = "This server's instance id",
        Callback    = function()
            if setclipboard then
                setclipboard(game.JobId)
                ctx.Notify("JobId copied")
            else
                ctx.Notify("No setclipboard in this executor", 5)
            end
        end,
    })

    ------------------------------------------------------------------ player
    ctx.Tab:AddParagraph({ Title = "Character", Content = "" })

    ctx.Tab:AddSlider("Universal_WalkSpeed", {
        Title    = "WalkSpeed",
        Default  = 16,
        Min      = 16,
        Max      = 200,
        Rounding = 0,
        Callback = function(value)
            local char = LocalPlayer.Character
            local hum  = char and char:FindFirstChildOfClass("Humanoid")
            if hum then hum.WalkSpeed = value end
        end,
    })

    ctx.Tab:AddSlider("Universal_JumpPower", {
        Title    = "JumpPower",
        Default  = 50,
        Min      = 50,
        Max      = 300,
        Rounding = 0,
        Callback = function(value)
            local char = LocalPlayer.Character
            local hum  = char and char:FindFirstChildOfClass("Humanoid")
            if hum then
                hum.UseJumpPower = true
                hum.JumpPower    = value
            end
        end,
    })

    ctx.Tab:AddButton({
        Title       = "Reset character",
        Description = "Breaks joints on your humanoid",
        Callback    = function()
            local char = LocalPlayer.Character
            local hum  = char and char:FindFirstChildOfClass("Humanoid")
            if hum then hum.Health = 0 end
        end,
    })

    ------------------------------------------------------------------ stats
    local statsParagraph = ctx.Tab:AddParagraph({
        Title   = "Stats",
        Content = "FPS: -   Ping: -",
    })

    ctx.Spawn(function()
        while ctx.IsAlive() do
            local fps, ping = "-", "-"
            pcall(function()
                local dt = RunService.RenderStepped:Wait()
                if type(dt) == "number" and dt > 0 then
                    fps = tostring(math.floor(1 / dt))
                end
            end)
            pcall(function()
                ping = math.floor(LocalPlayer:GetNetworkPing() * 1000) .. "ms"
            end)
            pcall(function()
                statsParagraph:SetDesc(("FPS: %s   Ping: %s"):format(fps, ping))
            end)
            task.wait(1)
        end
    end)
end

return M
]=]

local __cache = {}
local function __require(path)
    if __cache[path] ~= nil then return __cache[path] end
    local source = __sources[path]
    if not source then error('[Hub] unknown module: ' .. tostring(path), 0) end
    local chunk, err = loadstring(source, '@' .. path)
    if not chunk then error('[Hub] syntax error in ' .. path .. ': ' .. tostring(err), 0) end
    __cache[path] = chunk()
    return __cache[path]
